def single_number(nums):
    answer = 0
    for x in nums:
        answer ^= x
    return answer

def majority_element(nums):
    candidate = 0
    votes = 0
    for x in nums:
        if votes == 0:
            candidate = x
        votes += 1 if x == candidate else -1
    return candidate

